_original_reflection_feedback = bot.reflection_feedback


def reflection_feedback_day_specific(day, text, uid=None):
    if day in (1, 2):
        return _original_reflection_feedback(day, text, uid)
    template = DAY_FEEDBACK.get(day)
    if template:
        answer = text.strip()
        if len(answer) > 700:
            answer = answer[:700].rstrip() + "…"
        return template.format(answer=answer)
    return _original_reflection_feedback(day, text, uid)


bot.reflection_feedback = reflection_feedback_day_specific
